const fs = require('fs');
const http = require('http');
const path = require('path');

const endpoint = 'http://127.0.0.1:54251/status';

http.get(endpoint, (res) => {
  res.resume();
  res.on('end', () => {
    const outDir = path.join(__dirname, 'results');
    fs.mkdirSync(outDir, { recursive: true });
    fs.writeFileSync(
      path.join(outDir, 'status.json'),
      JSON.stringify({ status: res.statusCode }, null, 2) + '\n'
    );
    console.log(`status=${res.statusCode} -> results/status.json`);
  });
}).on('error', (err) => {
  console.error(`request failed: ${err.message}`);
  process.exit(1);
});

